// Works for Trello Trigger and Get Card outputs

const card = $json.action?.data?.card ?? $json;  // prefer nested if present
const board = $json.action?.data?.board ?? $json.board ?? {};
const list  = $json.action?.data?.list  ?? $json.list  ?? {};

// Collect text sources that may contain URLs
const text = [
  card.name,
  card.desc,
  $json.url,        // full card URL (if present)
  $json.shortUrl,   // short URL
  $json.shortLink,  // short code
].filter(Boolean).join('\n');

// Extract URLs (basic, non-greedy, stops at whitespace/closing parens)
const urls = Array.from(new Set(text.match(/https?:\/\/[^\s)]+/g) || []));

// Build a clean payload for downstream nodes
return [{
  json: {
    cardId: card.id ?? $json.id ?? null,
    boardId: $json.idBoard ?? board.id ?? null,
    listId:  $json.idList  ?? list.id  ?? null,
    name:    card.name ?? '',
    desc:    card.desc ?? '',
    urls,
    url: urls[0] ?? null
  }
}];

