// Works for 1..n items. Returns { cleanText, title, url, prompt } per item.

function stripSections(html) {
  html = html.replace(/<!--[\s\S]*?-->/g, '');
  html = html
    .replace(/<script[\s\S]*?<\/script>/gi, '')
    .replace(/<style[\s\S]*?<\/style>/gi, '')
    .replace(/<noscript[\s\S]*?<\/noscript>/gi, '')
    .replace(/<svg[\s\S]*?<\/svg>/gi, '')
    .replace(/<head[\s\S]*?<\/head>/gi, '');
  const noisy = [
    /(id|class)\s*=\s*"(?:nav|navbar|site-header|header|cookie|consent|subscribe|newsletter|breadcrumbs|footer|site-footer|sidebar)[^"]*"/gi,
    /(id|class)\s*=\s*'(?:nav|navbar|site-header|header|cookie|consent|subscribe|newsletter|breadcrumbs|footer|site-footer|sidebar)[^']*'/gi,
  ];
  for (const rx of noisy) {
    html = html.replace(new RegExp(`<([a-z0-9:-]+)([^>]*${rx.source}[^>]*)>[\\s\\S]*?<\\/\\1>`, 'gi'), '');
  }
  return html;
}

function stripTagsToText(html) {
  html = html.replace(/<(\/p|\/div|\/li|br|\/h[1-6]|\/section|\/article|\/tr)\b[^>]*>/gi, '\n');
  html = html.replace(/<[^>]+>/g, ' ');
  return html;
}

function decodeEntities(txt) {
  const map = { '&nbsp;': ' ', '&amp;': '&', '&lt;': '<', '&gt;': '>', '&quot;': '"', '&#39;': "'", '&apos;': "'" };
  txt = txt.replace(/&(nbsp|amp|lt|gt|quot|#39|apos);/g, m => map[m] || m);
  txt = txt
    .replace(/&#(\d+);/g, (_, d) => String.fromCharCode(parseInt(d, 10)))
    .replace(/&#x([0-9a-fA-F]+);/g, (_, h) => String.fromCharCode(parseInt(h, 16)));
  return txt;
}

function normalizeText(txt) {
  const boilerplateWords = [
    'cookie', 'privacy', 'terms', 'subscribe', 'login', 'sign in', 'sign up',
    'navigation', 'copyright', 'all rights reserved'
  ];
  let lines = txt
    .split('\n')
    .map(l => l.replace(/\s+/g, ' ').trim())
    .filter(l => l.length > 0);

  lines = lines.filter(l => {
    const lower = l.toLowerCase();
    if (l.length < 3) return false;
    if (boilerplateWords.some(w => lower.includes(w))) return false;
    return true;
  });

  txt = lines.join('\n');

  // 🧹 Dedupe repeated UI/template phrases
  txt = txt.replace(/\b(Apply now|Save for Later|Share this job|LinkedIn|Email|Questions\?|Ask by email|Explore the area|Share)\b(?!.*(Upload|CV|motivation)).*?(?=\n|$)/gi, '');

  txt = txt.replace(/(Contact the recruiter|Eelkje Nieuwland|Ask by email|Your place of work)[\s\S]*?(?=\n|$)/gi, '');
  txt = txt.replace(/\b(Apply now|Save for Later|Share this job|LinkedIn|Email)\b(\s+\1)+/gi, '$1');
  txt = txt.replace(/&[a-z]+;/gi, ' ');
  txt = txt.replace(/\n{2,}/g, '\n').replace(/[ \t]+/g, ' ').trim();

  return txt;
}

function extractTitle(html, fallback) {
  const titleTag = html.match(/<title[^>]*>([\s\S]*?)<\/title>/i);
  if (titleTag && titleTag[1]) return decodeEntities(titleTag[1].trim());
  const og = html.match(/<meta[^>]+property=["']og:title["'][^>]+content=["']([^"']+)["'][^>]*>/i);
  if (og && og[1]) return decodeEntities(og[1].trim());
  const h1 = html.match(/<h1[^>]*>([\s\S]*?)<\/h1>/i);
  if (h1 && h1[1]) return decodeEntities(h1[1].replace(/<[^>]+>/g, '').trim());
  return fallback || '';
}

return items.map(item => {
  const j = item.json || {};
  const html = j.data ?? j.html ?? j.body ?? j.content ?? j.page ?? j.raw ?? '';
  const url = (Array.isArray(j.urls) ? j.urls[0] : j.urls) ?? j.url ?? null;

  if (typeof html !== 'string' || html.trim() === '') {
    return { json: { cleanText: '', title: '', url, note: 'No HTML input' } };
  }

  const stripped = stripSections(html);
  const textOnly = stripTagsToText(stripped);
  const decoded = decodeEntities(textOnly);

  // Focus around job-relevant keywords
  const jobKeywords = /(responsibilit(y|ies)|requirements?|qualifications?|what you(?:'|’)?ll do|about the role|benefits|skills)/i;
  let focus = decoded;
  const idx = decoded.search(jobKeywords);
  if (idx > -1) {
    const start = Math.max(0, idx - 5000);
    const end = Math.min(decoded.length, idx + 9000);
    focus = decoded.slice(start, end);
  }

  // 🧹 Dedupe repeated template lines before normalization
  focus = focus.replace(/(Apply now|Save for Later|Share this job|Email|LinkedIn)+/gi, '$1');

  const cleanText = normalizeText(focus);
  const title = extractTitle(html, j.title);

  // Build a clean AI prompt
  const prompt = `
Act as a professional HR data analyst specializing in structured job-posting extraction.

Your task is to analyze the following job advertisement and return a precise, valid JSON object with these fields:

{
  "job_title": "",
  "company_name": "",
  "location": "",
  "salary_min": "",
  "salary_max": "",
  "salary_currency": "",
  "salary_type": "",
  "salary_status": "",
  "short_description": "",
  "responsibilities": [],
  "qualifications": [],
  "benefits": [],
  "employment_type": "",
  "experience_level": "",
  "industry": "",
  "skills": [],
  "education": "",
  "how_to_apply": "",
  "source_url": ""
}

Guidelines:
- Use plain text only, no markdown or code fences.
- Keep all content factual — do not invent company names or data.
- If salary information is missing, estimate a reasonable range based on context, job title, and seniority.
  - Set "salary_status" to "estimated" for inferred values, or "offered" if clearly stated.
- Retain all skills and soft skills (leadership, communication, teamwork, adaptability, etc.), List at least 8–10 skills, combining technical and behavioral ones (e.g., leadership, communication, adaptability, strategic thinking, problem solving).
- Include behavioral / cultural expectations as soft skills if listed under "How to succeed" or "About you".
- If a field is not mentioned, leave it as an empty string or empty array.
- Preserve any currency symbols and units (€, $, £, etc.).
- Summarize "short_description" in 3–4 sentences.
- Always output "source_url" as provided, even if null.
- JSON must be syntactically valid.

Job Title: ${title}

Input Job Ad Text:
${cleanText}

Source URL:
${url}
`.trim();

  return {
    json: { cleanText, title, url, prompt }
  };
});

let raw = $json.text || $json.response || $json.data || '';
let parsed;

try {
  parsed = JSON.parse(raw);
} catch (e) {
  const match = raw.match(/\{[\s\S]*\}/);
  if (match) {
    try { parsed = JSON.parse(match[0]); } catch {}
  }
}

if (!parsed) {
  return [{ json: { error: 'Failed to parse JSON', raw } }];
}

// ✅ Quality / completeness check
const required = ["job_title", "company_name", "location", "short_description"];
for (const key of required) {
  if (!parsed[key] || (typeof parsed[key] === 'string' && parsed[key].trim() === '')) {
    parsed.warning = (parsed.warning || []).concat(`Missing ${key}`);
  }
}

// ✅ Return clean, structured result
return [{ json: parsed }];

let raw = $json.text || $json.response || $json.data || '';
let parsed = null;

// Step 1: Trim noise & invisible characters
raw = raw.trim().replace(/[\u0000-\u001F]+/g, '');

// Step 2: Try parsing as-is
try {
  parsed = JSON.parse(raw);
} catch (e1) {
  // Step 3: Try to extract partial JSON
  let match = raw.match(/\{[\s\S]*$/); // take from first { to end of string
  if (match) {
    let jsonStr = match[0];

    // Step 4: Attempt to auto-close missing structures
    const openBrackets = (jsonStr.match(/\[/g) || []).length;
    const closeBrackets = (jsonStr.match(/\]/g) || []).length;
    const openBraces = (jsonStr.match(/\{/g) || []).length;
    const closeBraces = (jsonStr.match(/\}/g) || []).length;

    if (openBrackets > closeBrackets) jsonStr += ']';
    if (openBraces > closeBraces) jsonStr += '}';

    // Step 5: Clean trailing commas
    jsonStr = jsonStr.replace(/,\s*([\]}])/g, '$1');

    try {
      parsed = JSON.parse(jsonStr);
    } catch (e2) {
      // Step 6: Last resort — wrap entire string and fix quotes if needed
      jsonStr = jsonStr.replace(/"([^"]*)$/g, '$1"'); // close final quote
      if (openBrackets > closeBrackets) jsonStr += ']';
      if (openBraces > closeBraces) jsonStr += '}';

      try {
        parsed = JSON.parse(jsonStr);
      } catch (e3) {
        return [{ json: { error: 'Failed to recover JSON', raw } }];
      }
    }
  } else {
    return [{ json: { error: 'No JSON structure found', raw } }];
  }
}

// Step 7: Return result or fallback
return [{ json: parsed || { error: 'Empty parse result', raw } }];
